//! op-dbus-mirror: 1:1 D-Bus publication of internal databases
//!
//! This crate publishes the internal OVSDB and NonNet database structures as a
//! D-Bus object hierarchy without introducing a second source of truth.

use anyhow::Result;
use dashmap::DashMap;

/// Strongly-typed error for D-Bus mirror operations.
///
/// Keeps `anyhow` out of the public API surface while preserving
/// ergonomic `?` propagation inside the crate.
#[derive(Debug, thiserror::Error)]
pub enum MirrorError {
    #[error("D-Bus error: {0}")]
    Zbus(#[from] zbus::Error),

    #[error("serialization error: {0}")]
    Serialization(#[from] serde_json::Error),

    #[error("{0}")]
    Other(String),
}

impl From<anyhow::Error> for MirrorError {
    fn from(e: anyhow::Error) -> Self {
        Self::Other(e.to_string())
    }
}
