use serde_json::{Map, Value};
use std::collections::HashSet;
use std::sync::Arc;
use zbus::zvariant::{ObjectPath, OwnedObjectPath};
use zbus::{connection::Builder, Connection};

pub mod dbus_interface;
pub mod event;
pub mod event_dispatcher;
pub mod event_sources;
pub mod heartbeat;
pub mod jsonrpc_interface;
pub mod object;
pub mod session;
pub mod tree;

/// D-Bus publication service.
///
/// Responsible for maintaining mirror-management interfaces at /org/opdbus/v1/mirror/.
/// Plugin objects (at /org/opdbus/v1/plugins/) are served exclusively by op-grpc-bridge.
pub struct DbusMirror {
    ovsdb: Arc<OvsdbDbusClient>,
    nonnet: Arc<NonNetDb>,
    schema_engine: Option<Arc<SchemaEngine>>,
    connection: Connection,
    /// Published D-Bus object paths managed by this service.
    published_objects: DashMap<String, ()>,
    /// Current data and sequence numbers per object path
    current_data: DashMap<String, (Value, u64)>,
    /// Per-session state keyed by peer name
    pub sessions: DashMap<String, session::MirrorSession>,
}

impl DbusMirror {
    /// Create a new D-Bus publication service.
    pub async fn new(
        bus_type: BusType,
        ovsdb: Arc<OvsdbDbusClient>,
        nonnet: Arc<NonNetDb>,
        schema_engine: Option<Arc<SchemaEngine>>,
    ) -> std::result::Result<Self, MirrorError> {
        let connection = match bus_type {
            BusType::System => Builder::system()?.name("org.opdbus.v1.mirror")?.build().await?,
            BusType::Session => Builder::session()?.name("org.opdbus.v1.mirror")?.build().await?,
        };

        Ok(Self {
            ovsdb,
            nonnet,
            schema_engine,
            connection,
            published_objects: DashMap::new(),
            current_data: DashMap::new(),
            sessions: DashMap::new(),
        })
    }

